import QRCode from 'qrcode';
import { api, isMockMode } from '../lib/api.js';
import { longDate, money, escapeHtml } from '../lib/format.js';
import { icon, setTitle, toast } from '../lib/dom.js';
import { downloadTicketBundle } from '../lib/ticket-pdf.js';

export async function statusView() {
  setTitle('Order status');
  const hashToken = decodeURIComponent(location.hash.replace(/^#/, ''));
  const token = hashToken || sessionStorage.getItem('tixora-status-token');
  if (hashToken) sessionStorage.setItem('tixora-status-token', hashToken);
  const order = token ? await api.getOrder(token) : null;

  if (!token || !order) {
    return {
      meta: { section: 'public' },
      html: `<main id="main" class="status-empty page-shell" tabindex="-1">
        <p class="kicker">PRIVATE ORDER STATUS</p><h1>This page needs its private link.</h1>
        <p>Open the link from the purchaser’s email. A visible order number alone cannot reveal ticket or payment details.</p>
        <a class="button button--ink" href="/events" data-link>${icon('back')} See events</a>
      </main>`,
    };
  }

  const state = statusState(order);
  return {
    meta: { section: 'public' },
    html: `<main id="main" class="status-page" tabindex="-1" style="--event-accent:${order.event?.accent || '#e45a2a'}">
      <section class="status-banner status-banner--${state.tone}">
        <div class="status-banner__mark">${state.icon}</div>
        <div><p class="kicker">ORDER ${escapeHtml(order.displayReference)}</p><h1>${state.title}</h1><p>${state.body}</p></div>
      </section>
      <div class="status-layout page-shell">
        <section class="status-main">
          ${order.fulfillmentStatus === 'fulfilled' ? fulfilled(order) : pending(order)}
        </section>
        <aside class="order-receipt">
          <p class="kicker">ORDER RECEIPT</p>
          <h2>${escapeHtml(order.event?.name || 'Event')}</h2>
          <dl>
            <div><dt>Date</dt><dd>${order.event ? escapeHtml(longDate(order.event.startsAt)) : '—'}</dd></div>
            <div><dt>Venue</dt><dd>${escapeHtml(order.event?.venue || '—')}</dd></div>
            <div><dt>Ticket</dt><dd>${order.quantity} × ${escapeHtml(order.tier?.name || '')}</dd></div>
            <div><dt>Subtotal</dt><dd>${money(order.pricing.subtotalMinor)}</dd></div>
            <div><dt>Booking fee</dt><dd>${money(order.pricing.feeTotalMinor)}</dd></div>
            <div class="order-receipt__total"><dt>Paid</dt><dd>${money(order.pricing.totalMinor)}</dd></div>
          </dl>
          <p class="receipt-email">Purchaser copy: <strong>${escapeHtml(order.buyer.email)}</strong></p>
          ${isMockMode ? '<p class="demo-box"><strong>Demo:</strong> Email delivery is recorded locally. No message has left this browser.</p>' : ''}
        </aside>
      </div>
    </main>`,
    mount() {
      renderQrs(order);
      document.querySelector('[data-download-bundle]')?.addEventListener('click', async (event) => {
        const button = event.currentTarget;
        button.disabled = true;
        button.textContent = 'Building the PDF…';
        try { await downloadTicketBundle(order); toast('Ticket bundle downloaded.', 'success'); }
        catch (error) { console.error(error); toast('The PDF could not be built.', 'error'); }
        finally { button.disabled = false; button.innerHTML = `${icon('download')} Download all tickets`; }
      });
      const resend = document.querySelector('[data-resend-form]');
      resend?.addEventListener('submit', async (event) => {
        event.preventDefault();
        const button = resend.querySelector('button');
        button.disabled = true;
        try {
          await api.resend(token, new FormData(resend).get('email'));
          toast('Ticket email queued for delivery.', 'success');
        } catch (error) { toast(error.message, 'error'); }
        finally { button.disabled = false; }
      });
    },
  };
}

function fulfilled(order) {
  return `<div class="status-section-head"><div><p class="kicker">${order.tickets.length} NAMED TICKET${order.tickets.length === 1 ? '' : 'S'}</p><h2>Keep these QRs private.</h2></div><button class="button button--ink" data-download-bundle>${icon('download')} Download all tickets</button></div>
    <div class="ticket-stack">
      ${order.tickets.map((ticket, index) => `<article class="digital-ticket">
        <div class="digital-ticket__top"><span>${String(index + 1).padStart(2, '0')} / ${String(order.tickets.length).padStart(2, '0')}</span><strong>${escapeHtml(order.event.code)}</strong></div>
        <div class="digital-ticket__person"><small>ATTENDEE</small><h3>${escapeHtml(ticket.attendeeName)}</h3><span>${escapeHtml(order.tier.name)}</span></div>
        <div class="digital-ticket__qr"><canvas data-ticket-qr="${index}" aria-label="QR code for ${escapeHtml(ticket.attendeeName)}"></canvas><strong>${escapeHtml(ticket.number)}</strong></div>
        <div class="digital-ticket__foot"><span>ONE SCAN</span><span>${escapeHtml(order.event.name)}</span></div>
      </article>`).join('')}
    </div>
    <section class="resend-panel"><div><p class="kicker">NEED ANOTHER COPY?</p><h2>Resend to an address already on this order.</h2></div><form data-resend-form><label>Email address<input type="email" name="email" required value="${escapeHtml(order.buyer.email)}"></label><button class="button button--outline" type="submit">Resend ticket email ${icon('arrow')}</button></form></section>`;
}

function pending(order) {
  const exception = order.fulfillmentStatus === 'paid_exception';
  return `<section class="pending-panel">
    <p class="kicker">${exception ? 'PAID EXCEPTION' : 'ORDER IN PROGRESS'}</p>
    <h2>${exception ? 'No ticket has been issued.' : 'We are waiting for the verified payment event.'}</h2>
    <p>${exception ? 'The 15-minute hold ended before payment arrived and capacity is no longer available. The box office has this in its priority queue for a manual resolution.' : 'You can close this page. Paystack’s server confirmation—not the browser—moves the order forward.'}</p>
    <div class="pending-steps"><span class="is-done">Order created</span><span class="${order.paymentStatus === 'paid' ? 'is-done' : ''}">Payment verified</span><span>Tickets issued</span></div>
  </section>`;
}

function statusState(order) {
  if (order.fulfillmentStatus === 'fulfilled') return { tone: 'success', icon: icon('check', 34), title: 'Payment received. Your tickets are ready.', body: `Individual tickets have been prepared for ${order.quantity} attendee${order.quantity === 1 ? '' : 's'}.` };
  if (order.fulfillmentStatus === 'paid_exception') return { tone: 'warning', icon: icon('warning', 34), title: 'Payment received. The box office needs to step in.', body: 'No ticket was issued and capacity was not exceeded.' };
  return { tone: 'pending', icon: icon('ticket', 34), title: 'Payment confirmation is still pending.', body: 'This page updates only after the server verifies Paystack.' };
}

async function renderQrs(order) {
  await Promise.all(order.tickets.map((ticket, index) => {
    const canvas = document.querySelector(`[data-ticket-qr="${index}"]`);
    return canvas ? QRCode.toCanvas(canvas, ticket.qrPayload, { width: 180, margin: 2, errorCorrectionLevel: 'M', color: { dark: '#15130f', light: '#f4ecde' } }) : null;
  }));
}
