import { PDFDocument, StandardFonts, rgb } from 'pdf-lib';
import QRCode from 'qrcode';

function hexToRgb(hex) {
  const clean = hex.replace('#', '');
  const value = parseInt(clean.length === 3 ? clean.split('').map((c) => c + c).join('') : clean, 16);
  return rgb(((value >> 16) & 255) / 255, ((value >> 8) & 255) / 255, (value & 255) / 255);
}

function dataUriBytes(uri) {
  const binary = atob(uri.split(',')[1]);
  return Uint8Array.from(binary, (char) => char.charCodeAt(0));
}

function fit(text, font, max, start) {
  let size = start;
  while (size > 14 && font.widthOfTextAtSize(text, size) > max) size -= 1;
  return size;
}

export async function downloadTicketBundle(order) {
  const pdf = await PDFDocument.create();
  pdf.setTitle(`${order.event.name} — ${order.displayReference}`);
  pdf.setAuthor('Tixora');
  const regular = await pdf.embedFont(StandardFonts.Helvetica);
  const bold = await pdf.embedFont(StandardFonts.HelveticaBold);
  const ink = rgb(0.075, 0.07, 0.055);
  const paper = rgb(0.96, 0.93, 0.86);
  const accent = hexToRgb(order.event.accent || '#e45a2a');

  for (const ticket of order.tickets) {
    const page = pdf.addPage([420, 680]);
    page.drawRectangle({ x: 0, y: 0, width: 420, height: 680, color: paper });
    page.drawRectangle({ x: 0, y: 590, width: 420, height: 90, color: accent });
    page.drawText('TIXORA / ADMIT ONE', { x: 28, y: 642, size: 9, font: bold, color: ink });
    const titleSize = fit(order.event.name.toUpperCase(), bold, 364, 28);
    page.drawText(order.event.name.toUpperCase(), { x: 28, y: 608, size: titleSize, font: bold, color: ink });

    page.drawText('ATTENDEE', { x: 28, y: 558, size: 8, font: bold, color: rgb(.4, .38, .34) });
    page.drawText(ticket.attendeeName, { x: 28, y: 532, size: 18, font: bold, color: ink });
    page.drawText(order.tier.name.toUpperCase(), { x: 28, y: 501, size: 10, font: bold, color: accent });

    page.drawLine({ start: { x: 28, y: 482 }, end: { x: 392, y: 482 }, thickness: 1.5, color: ink });
    page.drawText('WHEN', { x: 28, y: 452, size: 8, font: bold, color: rgb(.4, .38, .34) });
    page.drawText(new Intl.DateTimeFormat('en-NG', { weekday: 'short', day: 'numeric', month: 'short', year: 'numeric', hour: 'numeric', minute: '2-digit', timeZone: 'Africa/Lagos' }).format(new Date(order.event.startsAt)), { x: 28, y: 433, size: 11, font: regular, color: ink });
    page.drawText('WHERE', { x: 28, y: 400, size: 8, font: bold, color: rgb(.4, .38, .34) });
    page.drawText(order.event.venue.slice(0, 58), { x: 28, y: 381, size: 11, font: regular, color: ink });

    const qrData = await QRCode.toDataURL(ticket.qrPayload, { margin: 2, width: 420, errorCorrectionLevel: 'M', color: { dark: '#13120e', light: '#f5eddd' } });
    const qr = await pdf.embedPng(dataUriBytes(qrData));
    page.drawImage(qr, { x: 116, y: 145, width: 188, height: 188 });
    const ticketWidth = bold.widthOfTextAtSize(ticket.number, 11);
    page.drawText(ticket.number, { x: (420 - ticketWidth) / 2, y: 122, size: 11, font: bold, color: ink });
    page.drawLine({ start: { x: 28, y: 92 }, end: { x: 392, y: 92 }, thickness: 1, dashArray: [5, 5], color: ink });
    page.drawText('Named ticket · One successful scan · Keep the QR private', { x: 28, y: 62, size: 9, font: regular, color: ink });
    page.drawText(`Order ${order.displayReference}`, { x: 28, y: 42, size: 8, font: regular, color: rgb(.4, .38, .34) });
  }

  const bytes = await pdf.save();
  const blob = new Blob([bytes], { type: 'application/pdf' });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = `${order.event.slug}-${order.displayReference}.pdf`;
  anchor.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}
